/// What the backend has when the source names nothing:
/// `-march=armv9.5-a+crc+crypto+fp+lse+lsfe+lse128+lsui+simd+pan+lor+ras+rdma+fp16+fp16fml+fprcvt+profile+sve+tme+fcma+jscvt+rcpc+rcpc2+dotprod+sha2+frintts+sb+predres+predres2+poe2+tev+aes+sm4+sha3+rng+ssbs+lscp+memtag+occmo+cmpbr+sve2+sve2-sm4+sve2-aes+sve2-sha3+sve2-bitperm+sme+sme-f64f64+sme-i16i64+sme2+bf16+i8mm+f32mm+f64mm+ls64+flagm+flagm2+pauth+xs+wfxt+mops+hbc+cssc+chk+gcs+the+rasv2+ite+d128+sve-b16b16+sve-bfscale+sme2p1+sve2p1+sve-f16f32mm+f8f32mm+f8f16mm+sve-aes+sve-aes2+ssve-aes+sve-bitperm+ssve-bitperm+rcpc3+cpa+faminmax+fp8+lut+brbe+sme-lutv2+fp8fma+fp8dot4+fp8dot2+ssve-fp8fma+ssve-fp8dot4+ssve-fp8dot2+sme-f8f32+sme-f8f16+sme-f16f16+sme-b16b16+pops+sve2p2+sme2p2+gcie+ssve-fexpa+sme-tmop+sme-mop4+mops-go+sve2p3+sme2p3+f16f32dot+f16f32mm+f16mm+sve-b16mm+mtetc+tlbid+sme-fa64`,
/// as `tools/xas-diff` runs the reference.
pub const DEFAULT: Set = [0xfffffffffff4ffff, 0xffffffffffffffff, 0xfffff];

/// `+sme` and the `+sve`, `+sve2` it drags in whatever else
/// was asked for; see [`super::cpu::parse_features`].
pub const SME: Set = [0x4000000, 0x0, 0x0];
pub const SVE_SVE2: Set = [0x10000200000, 0x0, 0x0];

/// `V8R`, which `src/arch/aarch64/sysreg.rs` asks about by
/// name: an ARMv8-R core has no EL3, so none of the
/// system-instruction operands that address it is available
/// there, however the rest of the target reads.
pub const V8R: Set = [0x80000, 0x0, 0x0];
